package at.foama.wien;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.android.controller.ActivityController;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;
import android.location.Location;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.net.*;
import java.io.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w227dp-h227dp-round-xhdpi") @LooperMode(LooperMode.Mode.PAUSED)
public class MultiCityTest {
    Repo repo;
    @Before public void setup(){RuntimeEnvironment.getApplication().getSharedPreferences("foama",0).edit().clear().commit();repo=new Repo(RuntimeEnvironment.getApplication());}
    Repo.Stop stop(String city){for(Repo.Stop s:repo.stops)if(s.city.equals(city)&&(!city.equals("wien")||s.modes.contains("metro")))return s;throw new AssertionError(city);}
    JSONObject row(Repo.Stop stop,String mode,long now)throws Exception{return new JSONObject().put("provider","transitous").put("stopId",stop.id).put("route","3").put("towards","Testziel").put("mode",mode).put("quality","live").put("scheduled",java.time.Instant.ofEpochMilli(now+120000).toString()).put("realtime",java.time.Instant.ofEpochMilli(now+180000).toString()).put("fetchedAt",java.time.Instant.ofEpochMilli(now-10000).toString());}
    JSONObject board(Repo.Stop stop,JSONArray rows)throws Exception{return new JSONObject().put("stations",new JSONArray().put(stop.id)).put("departures",rows);}
    @Test public void cataloguesAndFavoritesSurviveCityChangesWithoutSavingGps()throws Exception{
        for(String city:CityProfiles.IDS)assertNotNull(stop(city));Repo.Stop vienna=stop("wien"),graz=stop("graz");repo.toggleFavorite(vienna,"","");repo.toggleFavorite(graz,"3","Testziel","tram");String saved=repo.prefs.getString("favorites","");
        assertEquals(vienna.id,repo.orderedFavorites().get(0).stopId);repo.selectCity("graz");assertEquals(graz.id,repo.orderedFavorites().get(0).stopId);assertFalse(repo.reliableLocation());assertTrue(repo.manualLocation);assertEquals(saved,repo.prefs.getString("favorites",""));
        Repo restarted=new Repo(RuntimeEnvironment.getApplication());assertEquals("graz",restarted.cities.current());assertEquals(2,restarted.favorites.size());assertEquals("tram",restarted.orderedFavorites().get(0).mode);assertEquals("manual-city",restarted.currentLocation.getProvider());
        repo.selectCity("auto");assertNull(repo.currentLocation);assertEquals("wien",repo.cities.current());
    }
    @Test public void regionalMergeChecksExactStationTimeModeCancellationAndFreshness()throws Exception{
        Repo.Stop s=stop("graz"),foreign=stop("linz");long now=System.currentTimeMillis();JSONObject good=row(s,"tram",now),cancelled=row(s,"bus",now).put("cancelled",true),badMode=row(s,"boat",now),future=row(s,"tram",now).put("fetchedAt",java.time.Instant.ofEpochMilli(now+60000).toString());
        repo.mergeRegional(board(s,new JSONArray().put(good).put(row(foreign,"tram",now)).put(cancelled).put(badMode).put(future)),Arrays.asList(s),now);assertEquals(1,repo.departures.size());Repo.Departure d=repo.departures.get(0);assertEquals(s.id,d.stopKey);assertEquals(now-10000,d.fetchedAt);assertEquals("Live",d.quality);assertFalse(d.notice);
        repo.mergeRail(Arrays.asList(s));assertEquals(1,repo.departures.size());repo.saveCache();Repo restarted=new Repo(RuntimeEnvironment.getApplication());assertEquals(1,restarted.departures.size());
    }
    @Test public void salzburgIsScheduleOnlyAndSameNamedModesStaySeparate()throws Exception{
        Repo.Stop s=stop("salzburg");long now=System.currentTimeMillis();repo.mergeRegional(board(s,new JSONArray().put(row(s,"bus",now)).put(row(s,"sbahn",now))),Arrays.asList(s),now);assertEquals(2,repo.connections(s,"3","Testziel",true).size());for(Repo.Departure d:repo.departures){assertEquals(now+120000,d.when);assertEquals("Fahrplan",d.quality);}assertEquals(1,repo.connections(s,"3","Testziel",true,"bus").size());
        repo.toggleFavorite(s,"3","Testziel","bus");repo.toggleFavorite(s,"3","Testziel","sbahn");assertEquals(2,repo.favorites.size());repo.toggleFavorite(s,"3","Testziel","bus");assertEquals("sbahn",repo.favorites.get(0).mode);
    }
    @Test public void partialBoardsDoNotDeleteAnotherCityAndErrorsDoNotCrossProviders()throws Exception{
        Repo.Stop a=stop("graz"),b=stop("linz");long now=System.currentTimeMillis();repo.mergeRegional(board(a,new JSONArray().put(row(a,"tram",now))),Arrays.asList(a),now);repo.mergeRegional(board(b,new JSONArray().put(row(b,"bus",now))),Arrays.asList(a,b),now);assertEquals(2,repo.departures.size());repo.lastError="Wien offline";assertTrue(repo.fresh(repo.departures.get(0)));assertEquals("",repo.currentError(Arrays.asList(a)));repo.regionalError="Region offline";assertFalse(repo.fresh(repo.departures.get(0)));
    }
    @Test public void regionalRequestsPrioritizeVisibleStationsAndRotateAtMostThree(){ArrayList<Repo.Stop> selected=new ArrayList<>();for(Repo.Stop s:repo.stops)if(s.city.equals("graz")&&selected.size()<8)selected.add(s);Set<String> seen=new HashSet<>();for(int i=0;i<12;i++){List<Repo.Stop> request=repo.regionalRequestStops(selected,Collections.singleton(selected.get(7).id));assertEquals(3,request.size());assertEquals(selected.get(7),request.get(0));for(Repo.Stop s:request)seen.add(s.id);}assertEquals(8,seen.size());}
    @Test public void threeVisibleStationsAlwaysUseTheThreeAvailableSlots(){ArrayList<Repo.Stop> all=new ArrayList<>();for(Repo.Stop stop:repo.stops)if(stop.city.equals("graz")&&all.size()<7)all.add(stop);Set<String> visible=new HashSet<>(Arrays.asList(all.get(3).id,all.get(4).id,all.get(6).id));for(int i=0;i<7;i++)for(Repo.Stop stop:repo.regionalRequestStops(all,visible))assertTrue(visible.contains(stop.id));}
    @Test public void manualProfileRetainsRealInCityFixesAndRejectsForeignOnes(){long now=System.currentTimeMillis();Location a=new Location("test");a.setLatitude(48.22);a.setLongitude(16.37);a.setAccuracy(10);a.setTime(now);repo.acceptLocation(a);repo.selectCity("wien");assertFalse(repo.manualLocation);assertEquals(a.getLatitude(),repo.currentLocation.getLatitude(),0.00001);assertTrue(repo.reliableLocation());Location b=new Location(a);b.setLatitude(47.0707);b.setLongitude(15.4395);b.setTime(now+1);assertFalse(repo.acceptLocation(b));assertEquals(a.getLatitude(),repo.currentLocation.getLatitude(),0.00001);repo.selectCity("graz");assertTrue(repo.manualLocation);assertTrue(repo.acceptLocation(b));assertFalse(repo.manualLocation);assertEquals("graz",repo.cities.current());}
    static final class Connection extends HttpURLConnection {final String response;Connection(URL url,String response){super(url);this.response=response;}public void disconnect(){}public boolean usingProxy(){return false;}public void connect(){}public int getResponseCode(){return 200;}public InputStream getInputStream(){return new ByteArrayInputStream(response.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
    @Test public void regionalFetchUsesFixedEndpointAndSharedGateWithoutGps()throws Exception{Repo.Stop s=stop("graz");List<String> calls=new ArrayList<>();RequestScope request=new RequestScope(url->{calls.add(url.toString());return new Connection(url,board(s,new JSONArray().put(row(s,"tram",System.currentTimeMillis()))).toString());});repo.fetchDepartures(Arrays.asList(s),Collections.emptyList(),request);assertEquals(1,calls.size());assertTrue(calls.get(0).startsWith(BuildConfig.FOAMA_BASE_URL+"/api/regional/board?station=graz%3A"));assertFalse(calls.get(0).contains("lat"));assertEquals(1,repo.departures.size());repo.fetchDepartures(Arrays.asList(s),Collections.emptyList(),request);assertEquals(1,calls.size());request.cancel();try{repo.fetchDepartures(Arrays.asList(s),Collections.emptyList(),request);fail();}catch(java.io.InterruptedIOException expected){}}
    @Test public void regionalFavoritesAndRouteIdsRoundtripThroughImport()throws Exception{Repo.Stop s=stop("graz");JSONObject favorite=new JSONObject().put("stopId",s.id).put("route","3").put("towards","Testziel").put("mode","tram");TransferManager.Preview preview=TransferManager.preview(new JSONObject().put("format","foama-favorites-v1").put("favorites",new JSONArray().put(favorite)),repo);assertEquals(1,preview.favorites.length());repo.mergeTransfer(preview);assertEquals("tram",repo.favorites.get(0).mode);assertEquals(1,TransferManager.preview(new JSONObject().put("format","foama-favorites-v1").put("favorites",new JSONArray().put(favorite)),repo).duplicates);assertEquals(s.id,JourneyStore.place(new JSONObject().put("name",s.name).put("stopId",s.id)).getString("stopId"));}
    TextView find(View v,String label){if(v instanceof TextView&&((TextView)v).getText().toString().equals(label))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView child=find(((ViewGroup)v).getChildAt(i),label);if(child!=null)return child;}return null;}
    void click(MainActivity app,String label){View v=find(app.getWindow().getDecorView(),label);assertNotNull(label,v);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();assertTrue(v.performClick());}
    @Test public void manualSelectionLivesInSettingsAndBackReturnsToOriginalView(){ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=controller.get();try{assertNull(find(app.getWindow().getDecorView(),"Stadtprofil"));click(app,"Mehr");click(app,"Stadtprofil");click(app,"Salzburg");assertEquals("salzburg",app.repo.cities.current());assertTrue(app.repo.manualLocation);assertFalse(app.repo.reliableLocation());app.navigateBack();assertEquals("more",app.screen);app.navigateBack();assertEquals("home",app.screen);assertNotNull(find(app.getWindow().getDecorView(),app.repo.locationStatus()));assertNull(find(app.getWindow().getDecorView(),"Stadtprofil"));}finally{controller.stop().destroy();}}
}
